CREATE OR REPLACE FUNCTION public.check_l2_provenance_exists()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.normative_polarity IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM structured_coding_provenance WHERE proposition_id=NEW.id AND field_name='normative_polarity') THEN
    RAISE EXCEPTION 'propositions.id=% has normative_polarity set with no structured_coding_provenance row. Insert provenance in the same transaction.', NEW.id;
  END IF;
  IF NEW.scope_generality IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM structured_coding_provenance WHERE proposition_id=NEW.id AND field_name='scope_generality') THEN
    RAISE EXCEPTION 'propositions.id=% has scope_generality set with no structured_coding_provenance row.', NEW.id;
  END IF;
  IF NEW.comparison_object_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM structured_coding_provenance WHERE proposition_id=NEW.id AND field_name='comparison_object_id') THEN
    RAISE EXCEPTION 'propositions.id=% has comparison_object_id set with no structured_coding_provenance row.', NEW.id;
  END IF;
  RETURN NEW;
END; $function$
